export function icon(name: IconName, options: IconOptions = {}): SVGSVGElement {
  const size = options.size ?? 14;
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 16 16');
  svg.setAttribute('width', String(size));
  svg.setAttribute('height', String(size));
  svg.setAttribute('fill', 'currentColor');
  svg.setAttribute('class', `v-icon codicon-${CODICON_SOURCE[name as Exclude<IconName, 'pulse-dot'>] ?? name} v-icon-${name}${options.className ? ` ${options.className}` : ''}`);
  if (options.label) {
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', options.label);
  } else {
    svg.setAttribute('aria-hidden', options.ariaHidden === false ? 'false' : 'true');
  }
  svg.setAttribute('focusable', 'false');
  svg.innerHTML = ICONS[name] ?? '';
  return svg;
}
